-- Phase 4 placeholder decoration library. These are original, hand-drawn
-- flat-SVG shapes authored for this project (embedded as data: URIs, so
-- no Storage bucket is needed to see them work) — NOT a Kenney import.
-- Real Kenney sourcing (download, license verification per
-- docs/phase-1/08-licensing-review.md, upload to Storage) needs a live
-- Supabase Storage bucket and manual license verification per asset,
-- neither of which this environment can do; swap these rows out (and add
-- real entries to ASSET_LICENSES.md) once that pass happens.
insert into asset_licenses (
  id, source_url, creator, license, downloaded_at, attribution_required, modification_notes
)
values (
  '00000000-0000-0000-0000-000000000001',
  'https://github.com/Gariyuuu/yume',
  'Yume project (placeholder art)',
  'CC0 (original work)',
  current_date,
  false,
  'Hand-authored flat-SVG placeholders standing in for a real Kenney CC0 import — see ASSET_LICENSES.md.'
)
on conflict (id) do nothing;

